21	// Простейший ограничитель перебора паролей (в памяти процесса; для кластера — Redis).
22	const MAX_ATTEMPTS = 5;
23	const WINDOW_MS = 5 * 60_000;
24	const attempts = new Map<string, { count: number; resetAt: number }>();
25	
26	function isRateLimited(key: string): boolean {
27	  const now = Date.now();
28	  const entry = attempts.get(key);
29	  if (!entry || entry.resetAt < now) return false;
30	  return entry.count >= MAX_ATTEMPTS;
31	}
32	
33	function registerFailure(key: string): void {
34	  const now = Date.now();
35	  const entry = attempts.get(key);
36	  attempts.set(key, entry && entry.resetAt > now ? { ...entry, count: entry.count + 1 } : { count: 1, resetAt: now + WINDOW_MS });
37	}
38	
39	const INTERNAL_ORIGIN = "http://fms.internal";
40	
41	/**
42	 * Разрешаем редирект только на внутренние пути (защита от open redirect).
43	 * Разбираем как URL: браузер трактует "/\evil.com" как "//evil.com", поэтому префиксной проверки мало.
44	 */
45	function safeNext(next: string | undefined): string {
46	  if (!next || !next.startsWith("/") || next.includes("\\")) return "/";
47	  try {
48	    const url = new URL(next, INTERNAL_ORIGIN);
49	    if (url.origin !== INTERNAL_ORIGIN || url.pathname.startsWith("/login")) return "/";
50	    return `${url.pathname}${url.search}`;
51	  } catch {
52	    return "/";
53	  }
54	}
