57	  const parsed = loginSchema.safeParse({
58	    email: formData.get("email"),
59	    password: formData.get("password"),
60	    next: formData.get("next") ?? undefined,
61	  });
62	  if (!parsed.success) {
63	    return { error: parsed.error.issues[0]?.message ?? "Проверьте данные", email: String(formData.get("email") ?? "") };
64	  }
65	
66	  const { email, password, next } = parsed.data;
67	  if (isRateLimited(email)) {
68	    return { error: "Слишком много попыток входа. Повторите через 5 минут.", email };
69	  }
70	
71	  const user = await prisma.user.findUnique({ where: { email } });
72	  const isValid = user ? await bcrypt.compare(password, user.passwordHash) : false;
73	  if (!user || !isValid) {
74	    registerFailure(email);
75	    return { error: "Неверный email или пароль", email };
76	  }
77	
78	  attempts.delete(email);
79	  await createSessionCookie({ userId: user.id, email: user.email, name: user.name, role: user.role });
80	  redirect(safeNext(next));
81	}
