391	/**
392	 * CSV для русскоязычного Excel: UTF-8 с BOM (иначе кириллица превращается в «кракозябры»),
393	 * разделитель «;» (запятая — десятичный разделитель в ru-RU), переводы строк CRLF.
394	 */
395	import { formatDate } from "./format";
396	
397	export const CSV_BOM = String.fromCharCode(0xfeff); // UTF-8 BOM, U+FEFF
398	const DELIMITER = ";";
399	const LINE_BREAK = "\r\n";
400	/** Символы, с которых Excel начинает формулу — защита от CSV/формула-инъекций. */
401	const FORMULA_PREFIX = /^[=+\-@\t\r]/;
402	const NEEDS_QUOTES = /[";\r\n]/;
403	/** Телефон вида «+7 812 336-50-20»: только безопасные символы — можно отдать как текстовую константу Excel. */
404	const PHONE_LIKE = /^\+[\d\s()-]+$/;
405	
406	export type CsvCell = string | number | boolean | Date | null | undefined;
407	
408	export interface CsvColumn<T> {
409	  header: string;
410	  value: (row: T) => CsvCell;
411	}
412	
413	function formatNumber(value: number): string {
414	  if (!Number.isFinite(value)) return "";
415	  const text = Number.isInteger(value) ? String(value) : value.toFixed(2);
416	  return text.replace(".", ",");
417	}
418	
419	function quote(value: string): string {
420	  return `"${value.replace(/"/g, '""')}"`;
421	}
422	
423	function escapeText(value: string): string {
424	  // ="+7 …" Excel показывает как обычный текст, без апострофа; шаблон PHONE_LIKE исключает инъекцию.
425	  if (PHONE_LIKE.test(value)) return quote(`="${value}"`);
426	  const safe = FORMULA_PREFIX.test(value) ? `'${value}` : value;
427	  return NEEDS_QUOTES.test(safe) ? quote(safe) : safe;
428	}
429	
430	export function formatCsvCell(value: CsvCell): string {
431	  if (value === null || value === undefined) return "";
432	  if (typeof value === "number") return formatNumber(value);
433	  if (typeof value === "boolean") return value ? "Да" : "Нет";
434	  if (value instanceof Date) return formatDate(value);
435	  return escapeText(value);
436	}
437	
438	export function buildCsv<T>(rows: readonly T[], columns: readonly CsvColumn<T>[]): string {
439	  const header = columns.map((c) => escapeText(c.header)).join(DELIMITER);
440	  const lines = rows.map((row) => columns.map((c) => formatCsvCell(c.value(row))).join(DELIMITER));
441	  return CSV_BOM + [header, ...lines].join(LINE_BREAK);
442	}
