444	/** Имя файла с датой выгрузки: fms-registry_2026-10-26.csv */
445	export function csvFilename(prefix: string, now: Date = new Date()): string {
446	  return `${prefix}_${now.toISOString().slice(0, 10)}.csv`;
447	}
