449	/** Скачивание в браузере (только клиентский код). */
450	export function downloadCsv(filename: string, content: string): void {
451	  const blob = new Blob([content], { type: "text/csv;charset=utf-8" });
452	  const url = URL.createObjectURL(blob);
453	  const link = document.createElement("a");
454	  link.href = url;
455	  link.download = filename;
456	  link.rel = "noopener";
457	  document.body.appendChild(link);
458	  link.click();
459	  link.remove();
460	  // Даём браузеру начать загрузку, затем освобождаем память.
461	  setTimeout(() => URL.revokeObjectURL(url), 1_000);
462	}
