623	/**
624	 * ISO 6346 — идентификация грузовых контейнеров.
625	 * Формат: 3 буквы кода владельца + 1 буква идентификатора категории (U/J/Z)
626	 * + 6 цифр серийного номера + 1 контрольная цифра. Пример: TKRU 204812-?
627	 */
628	
629	// Буквы кодируются числами 10..38, пропуская кратные 11 (11, 22, 33).
630	const LETTER_VALUES: Readonly<Record<string, number>> = (() => {
631	  const values: Record<string, number> = {};
632	  let value = 10;
633	  for (const letter of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") {
634	    if (value % 11 === 0) value += 1;
635	    values[letter] = value;
636	    value += 1;
637	  }
638	  return values;
639	})();
640	
641	const STANDARD_CATEGORY_IDS = ["U", "J", "Z"] as const;
642	const BIC_PATTERN = /^([A-Z]{4})(\d{6})(\d)?$/;
643	
644	/** Убирает пробелы, дефисы и приводит к верхнему регистру: "exex 402918-3" → "EXEX4029183". */
645	export function normalizeBic(raw: string): string {
646	  return raw.toUpperCase().replace(/[^A-Z0-9]/g, "");
647	}
648	
649	/** Контрольная цифра для первых 10 символов (4 буквы + 6 цифр). */
650	export function computeCheckDigit(first10: string): number {
651	  const code = normalizeBic(first10);
652	  if (!/^[A-Z]{4}\d{6}$/.test(code)) {
653	    throw new Error(`Ожидается 4 буквы и 6 цифр, получено: "${first10}"`);
654	  }
655	  let sum = 0;
656	  for (let i = 0; i < 10; i++) {
657	    const ch = code[i];
658	    const charValue = i < 4 ? LETTER_VALUES[ch] : Number(ch);
659	    sum += charValue * 2 ** i;
660	  }
661	  return (sum % 11) % 10;
662	}
663	
664	/** Собирает полный номер с контрольной цифрой: ("EXEX", "402918") → "EXEX4029183". */
665	export function buildBic(ownerPrefix: string, serial: string): string {
666	  const base = `${ownerPrefix.toUpperCase()}${serial}`;
667	  return `${base}${computeCheckDigit(base)}`;
668	}
669	
670	export interface BicValidation {
671	  valid: boolean;
672	  normalized: string;
673	  expectedCheckDigit: number | null;
674	  errors: string[];
675	  warnings: string[];
676	}
677	
678	export function validateBic(raw: string): BicValidation {
679	  const normalized = normalizeBic(raw);
680	  const result: BicValidation = { valid: false, normalized, expectedCheckDigit: null, errors: [], warnings: [] };
681	  const match = BIC_PATTERN.exec(normalized);
682	
683	  if (!match) {
684	    result.errors.push("Формат: 4 буквы + 6 цифр + контрольная цифра (например, TKRU 204812-?)");
685	    return result;
686	  }
687	
688	  const [, prefix, serial, checkDigit] = match;
689	  const expected = computeCheckDigit(prefix + serial);
690	  result.expectedCheckDigit = expected;
691	
692	  if (checkDigit === undefined) {
693	    result.errors.push(`Не указана контрольная цифра. Ожидается: ${expected}`);
694	  } else if (Number(checkDigit) !== expected) {
695	    result.errors.push(`Неверная контрольная цифра: ${checkDigit}, ожидается ${expected}`);
696	  }
697	
698	  if (!STANDARD_CATEGORY_IDS.includes(prefix[3] as (typeof STANDARD_CATEGORY_IDS)[number])) {
699	    result.warnings.push(
700	      `4-й символ «${prefix[3]}» не является стандартным идентификатором категории (U/J/Z)`,
701	    );
702	  }
703	
704	  result.valid = result.errors.length === 0;
705	  return result;
706	}
707	
708	/** Отображение: "EXEX4029183" → "EXEX 402918-3". */
709	export function formatBic(normalized: string): string {
710	  const code = normalizeBic(normalized);
711	  if (code.length !== 11) return code;
712	  return `${code.slice(0, 4)} ${code.slice(4, 10)}-${code.slice(10)}`;
713	}
