      .filter((e) => e.containerId === unit.id && REVENUE_EVENTS.has(e.type as string))
      .reduce((sum, e) => sum + ((e.amountUsd as number | null) ?? 0), 0);
    expect(unit.totalRevenueUsd, String(unit.bicCode)).toBeCloseTo(booked, 2);
  }
});

