/**
 * Демо-режим (DEMO_MODE=true): быстрый вход в 1 клик, предзаполненный пароль, гид для проверяющего
 * и кнопка «Сбросить демо-данные». По умолчанию выключен — на боевом стенде этих функций нет.
 */
export const DEMO_CREDENTIALS = { email: "admin@exportexpert.ru", password: "Export2026!" } as const;

export function isDemoMode(env: Record<string, string | undefined> = process.env): boolean {
  return env.DEMO_MODE === "true";
}

import { describe, expect, test } from "vitest";
import { isDemoMode } from "./demo-mode";

describe("DEMO_MODE flag", () => {
  test("is off when the variable is missing — production-safe default", () => {
    expect(isDemoMode({})).toBe(false);
  });

  test("is on only for the exact value 'true'", () => {
    expect(isDemoMode({ DEMO_MODE: "true" })).toBe(true);
    expect(isDemoMode({ DEMO_MODE: "1" })).toBe(false);
    expect(isDemoMode({ DEMO_MODE: "false" })).toBe(false);
  });
});

