import { describe, expect, test } from "vitest";
import { isDemoMode } from "./demo-mode";

describe("DEMO_MODE flag", () => {
  test("is off when the variable is missing — production-safe default", () => {
    expect(isDemoMode({})).toBe(false);
  });

  test("is on only for the exact value 'true'", () => {
    expect(isDemoMode({ DEMO_MODE: "true" })).toBe(true);
    expect(isDemoMode({ DEMO_MODE: "1" })).toBe(false);
    expect(isDemoMode({ DEMO_MODE: "false" })).toBe(false);
  });
});

